/**
 * Dispatcher configuration — read once at startup from environment variables.
 */

export interface DispatcherConfig {
  /** Redis connection URL (e.g. redis://redis:6379). */
  redisUrl: string;
  /** Base URL of the broker service (e.g. http://broker:7000). */
  brokerUrl: string;
  /** Maximum number of concurrent executor containers (global cap). */
  maxConcurrent: number;
  /** Number of delivery attempts before routing a job to the DLQ. */
  maxDeliveries: number;
  /**
   * TTL (ms) for the per-handle spawn lock.
   * Must exceed worst-case docker pull + docker run time.
   * Default: 5 minutes.
   */
  spawnLockTtlMs: number;
  /** Unique name for this dispatcher instance within the consumer group. */
  consumerId: string;
  /** Docker binary path. Default: "docker". */
  dockerBin: string;
  /** Executor container image. Default: "executor:current". */
  executorImage: string;
  /**
   * Host path to the runner-wrapper directory (mounted read-only at /platform
   * inside the container). Default: "/workflow/runtime/runner-wrapper".
   */
  platformBinDir: string;
  /**
   * Host directory under which per-handle workspace dirs live.
   * Bind-mounted to /workspace inside the container.
   * EXECUTOR_WORKDIR inside the container is always set to /workspace.
   */
  workspacesDir: string;
  /** Docker bridge network all containers share. Default: "agents-net". */
  dockerNetwork: string;
  /** XREADGROUP BLOCK timeout in ms. Default: 5 000 ms. */
  pollBlockMs: number;
  /** XAUTOCLAIM min-idle-time in ms (jobs older than this are reclaimed). Default: 30 000 ms. */
  xautoclaimMinIdleMs: number;
  /** Batch size for XREADGROUP and XAUTOCLAIM. Default: 10. */
  batchSize: number;
}

function env(name: string, fallback?: string): string {
  const val = process.env[name] ?? fallback;
  if (val === undefined) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return val;
}

function envInt(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw === undefined) return fallback;
  const n = parseInt(raw, 10);
  if (isNaN(n)) throw new Error(`${name} must be an integer; got: ${raw}`);
  return n;
}

export function loadConfig(): DispatcherConfig {
  return {
    redisUrl: env("REDIS_URL", "redis://redis:6379"),
    brokerUrl: env("BROKER_URL", "http://broker:7000"),
    maxConcurrent: envInt("DISPATCHER_MAX_CONCURRENT", 5),
    maxDeliveries: envInt("DISPATCHER_MAX_DELIVERIES", 5),
    spawnLockTtlMs: envInt("DISPATCHER_SPAWN_LOCK_TTL_MS", 300_000),
    consumerId: env("DISPATCHER_CONSUMER_ID", `dispatcher-${process.pid}`),
    dockerBin: env("DOCKER_BIN", "docker"),
    executorImage: env("EXECUTOR_IMAGE", "executor:current"),
    platformBinDir: env("PLATFORM_BIN_DIR", "/workflow/runtime/runner-wrapper"),
    workspacesDir: env("WORKSPACES_DIR"),
    dockerNetwork: env("DOCKER_NETWORK", "agents-net"),
    pollBlockMs: envInt("DISPATCHER_POLL_BLOCK_MS", 5_000),
    xautoclaimMinIdleMs: envInt("DISPATCHER_XAUTOCLAIM_MIN_IDLE_MS", 30_000),
    batchSize: envInt("DISPATCHER_BATCH_SIZE", 10),
  };
}

