1	/**
2	 * DockerSpawner — relocated from the orchestrator's DockerRunAdapter.
3	 *
4	 * Responsibilities:
5	 *   - Accepts a DispatchJob + credentials and spawns an executor container.
6	 *   - Reconciles EXECUTOR_WORKDIR vs. /workspace bind-mount: the host
7	 *     workspacesDir/exec-<handle> is mounted at /workspace inside the
8	 *     container; EXECUTOR_WORKDIR is always set to /workspace so the
9	 *     executor writes land on the bind-mounted volume, not the ephemeral layer.
10	 *   - Sets LOG_SINK=none so the executor logs to stdout rather than the
11	 *     management repo (standalone path).
12	 *   - Checks whether a container labelled platform.handle=<handle> already
13	 *     exists (post-spawn backstop to avoid duplicate containers).
14	 *
15	 * It does NOT hold a supervision map or broker connection — those concerns
16	 * belong to the dispatch stream consumer.
17	 */
18	
19	import { execFile } from "node:child_process";
20	import { promisify } from "node:util";
21	import type { DispatchJob } from "@workflow/runtime-abi";
22	
23	const execFileAsync = promisify(execFile);
24	
25	export interface DockerSpawnerOpts {
26	  dockerBin?: string;
27	  executorImage?: string;
28	  platformBinDir?: string;
29	  workspacesDir: string;
30	  dockerNetwork?: string;
31	  runnerEntrypoint?: string;
32	}
33	
34	export interface SpawnResult {
35	  containerId: string;
36	}
37	
38	export class DockerSpawner {
39	  private readonly dockerBin: string;
40	  private readonly executorImage: string;
41	  private readonly platformBinDir: string;
42	  private readonly workspacesDir: string;
43	  private readonly dockerNetwork: string;
44	  private readonly runnerEntrypoint: string;
45	
46	  constructor(opts: DockerSpawnerOpts) {
47	    this.dockerBin = opts.dockerBin ?? "docker";
48	    this.executorImage = opts.executorImage ?? "executor:current";
49	    this.platformBinDir = opts.platformBinDir ?? "/workflow/runtime/runner-wrapper";
50	    this.workspacesDir = opts.workspacesDir;
51	    this.dockerNetwork = opts.dockerNetwork ?? "agents-net";
52	    this.runnerEntrypoint = opts.runnerEntrypoint ?? "/platform/runner.js";
53	  }
54	
55	  /**
56	   * Check whether a container with the given platform.handle label already
57	   * exists (running or exited). Returns the container ID if found, or null.
58	   *
59	   * This is the post-spawn backstop — it is not a substitute for the
60	   * pre-spawn spawn lock (SET NX PX), which closes the TOCTOU window.
61	   */
62	  async findExistingContainer(handle: string): Promise<string | null> {
63	    try {
64	      const { stdout } = await execFileAsync(this.dockerBin, [
65	        "ps", "-a",
66	        "--filter", `label=platform.handle=${handle}`,
67	        "--format", "{{.ID}}",
68	      ]);
69	      const id = stdout.trim();
70	      return id.length > 0 ? id : null;
71	    } catch {
72	      return null;
73	    }
74	  }
75	
76	  /**
77	   * Spawn a container for the given dispatch job.
78	   *
79	   * The host workspacesDir/exec-<handle> is mounted at /workspace.
80	   * EXECUTOR_WORKDIR inside the container is always /workspace — this
81	   * reconciles the EXECUTOR_WORKDIR (host path) vs. /workspace bind-mount
82	   * mismatch: the executor derives its impl/mgmt subdirs from /workspace,
83	   * so writes land on the bind-mounted volume rather than the ephemeral layer.
84	   *
85	   * LOG_SINK=none disables the git flush on the standalone path.
86	   */
87	  async spawn(
88	    job: DispatchJob,
89	    githubToken: string,
90	    sshPrivateKey: string,
91	  ): Promise<SpawnResult> {
92	    const containerName = `exec-${job.handle}`;
93	    const containerWorkdir = "/workspace";
94	
95	    const envArgs: string[] = [
96	      "-e", `TASK_ID=${job.task_id}`,
97	      "-e", `FEATURE_ID=${job.feature_id}`,
98	      "-e", `WORKSPACE_ID=${job.workspace_id}`,
99	      "-e", `TASK_REPO_URL=${job.task_repo_url}`,
100	      "-e", `TASK_REPO_BRANCH=${job.task_repo_branch}`,
101	      "-e", `TASK_BASE_BRANCH=${job.task_base_branch}`,
102	      "-e", `TASK_REPO_BASE_BRANCH=${job.task_repo_base_branch}`,
103	      // Reconciled: always /workspace inside the container.
104	      "-e", `EXECUTOR_WORKDIR=${containerWorkdir}`,
105	      "-e", `MGMT_REPO_URL=${job.mgmt_repo_url}`,
106	      "-e", `RESULT_PATH=${containerWorkdir}/result.json`,
107	      "-e", `CALLBACK_URL=${job.callback_url}`,
108	      "-e", `HANDLE=${job.handle}`,
109	      "-e", `NONCE=${job.nonce}`,
110	      "-e", `GITHUB_TOKEN=${githubToken}`,
111	      "-e", `LOG_SINK=none`,
112	    ];
113	
114	    if (sshPrivateKey) {
115	      envArgs.push("-e", `SSH_PRIVATE_KEY=${sshPrivateKey}`);
116	    }
117	    if (job.budget_tokens !== undefined) {
118	      envArgs.push("-e", `BUDGET_TOKENS=${job.budget_tokens}`);
119	    }
120	    if (job.implementation_model) {
121	      envArgs.push("-e", `IMPLEMENTATION_MODEL=${job.implementation_model}`);
122	    }
123	
124	    const volumeArgs = [
125	      "-v", `${this.platformBinDir}:/platform:ro`,
126	      "-v", `${this.workspacesDir}/exec-${job.handle}:/workspace:rw`,
127	    ];
128	
