/**
 * local-docker profile factory (T5 — standalone-executor-hardening).
 *
 * Bundles the decoupled adapter set into a RuntimePorts instance for the
 * M:N multi-container topology: the orchestrator enqueues a credential-free
 * DispatchJob to a Redis Stream; the dispatcher service (T4) consumes, injects
 * credentials, and spawns executor containers.
 *
 * The orchestrator is unprivileged on this path — no Docker socket, no
 * credential resolution, no docker run.
 *
 * Adapter set:
 *   ExecutorPort         → QueueDispatchAdapter  (XADD to dispatch Redis Stream)
 *   CompletionBrokerPort → HttpBrokerAdapter     (calls Go broker service at BROKER_URL)
 *   WorkflowState        → GitWorkflowStateAdapter
 *   Credential           → EnvCredentialAdapter  (retained for orchestrator's own git ops)
 *   WorkspacePull        → GitClonePullAdapter
 *   EventEmitter         → StdoutJsonEmitter
 *   Scheduler            → SimpleSleepScheduler
 *   Clock                → RealClock
 *
 * Topology:
 *   - All orchestrator containers, dispatcher containers, broker container,
 *     and Redis container share the `agents-net` bridge network.
 *   - Orchestrators have NO Docker socket mount (they no longer spawn containers).
 *   - The dispatcher holds the Docker socket and credentials.
 *   - Runners reach the broker at http://broker:7000/callback via service-name DNS.
 *   - Any orchestrator drains any completion (opportunistic M:N drain).
 */

import type { RuntimePorts } from "../runtime-ports.js";
import {
  QueueDispatchAdapter,
  type QueueDispatchAdapterOpts,
} from "../executor/queue-dispatch.js";
import { HttpBrokerAdapter, type HttpBrokerAdapterOpts } from "../broker/http.js";
import { GitWorkflowStateAdapter } from "../infra/workflow-state/git.js";
import { EnvCredentialAdapter } from "../infra/credential/env.js";
import { GitClonePullAdapter } from "../infra/workspace-pull/git-clone-pull.js";
import { StdoutJsonEmitter } from "../infra/emitter/stdout-json.js";
import { SimpleSleepScheduler } from "../infra/scheduler/simple-sleep.js";
import { RealClock } from "../infra/clock/real.js";

export interface LocalDockerProfileOpts {
  /** Options forwarded to QueueDispatchAdapter. */
  executor?: QueueDispatchAdapterOpts;
  /** Options forwarded to HttpBrokerAdapter. */
  broker?: HttpBrokerAdapterOpts;
  /** Base URL of the Go broker service. Defaults to http://broker:7000. */
  brokerUrl?: string;
  /** Redis URL for the dispatch stream. Defaults to REDIS_URL env var or redis://redis:6379. */
  redisUrl?: string;
  /** Git identity for WorkflowStatePort operations. */
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
}

/** The broker is part of the profile bundle so callers can call getCallbackUrl(). */
export interface LocalDockerProfileBundle extends RuntimePorts {
  broker: HttpBrokerAdapter;
  executor: QueueDispatchAdapter;
}

/**
 * Create a RuntimePorts bundle wired for the local-docker profile.
 *
 * The broker's getCallbackUrl() returns the Go broker service callback URL
 * (e.g. http://broker:7000/callback). Pass this to ExecutorPortInput as
 * callbackUrl when submitting tasks.
 *
 * Example:
 *   const bundle = createLocalDockerProfile({ gitAuthorEmail: '...', brokerUrl: 'http://broker:7000' });
 *   const callbackUrl = bundle.broker.getCallbackUrl();
 *   // pass bundle to orchestrator concerns...
 *   await bundle.executor.close(); // on graceful shutdown
 */
export function createLocalDockerProfile(
  opts: LocalDockerProfileOpts,
): LocalDockerProfileBundle {
  const brokerUrl = opts.brokerUrl ?? opts.broker?.brokerUrl ?? "http://broker:7000";
  const broker = new HttpBrokerAdapter(opts.broker ?? { brokerUrl });
  const executor = new QueueDispatchAdapter({
    ...opts.executor,
    broker,
    redisUrl: opts.redisUrl ?? opts.executor?.redisUrl,
  });
  return {
    executor,
    broker,
    workflowState: new GitWorkflowStateAdapter({
      gitAuthorEmail: opts.gitAuthorEmail,
      gitAuthorName: opts.gitAuthorName,
      sshKeyPath: opts.sshKeyPath,
    }),
    credential: new EnvCredentialAdapter(),
    workspacePull: new GitClonePullAdapter(),
    emitter: new StdoutJsonEmitter(),
    scheduler: new SimpleSleepScheduler(),
    clock: new RealClock(),
  };
}

