/**
 * QueueDispatchAdapter — ExecutorPort adapter for the local-docker profile (T5).
 *
 * submit() registers handle+nonce with the broker, then XADDs a credential-free
 * DispatchJob to the dispatch Redis Stream. The dispatcher service (T4) consumes
 * jobs via XREADGROUP, injects credentials, and spawns executor containers.
 *
 * The orchestrator is unprivileged on this path: no Docker socket, no credential
 * resolution, no docker run. It only enqueues.
 *
 * ack() delegates to broker.ack() — container cleanup is the dispatcher's concern.
 */

import { createClient, type RedisClientType } from "redis";
import type {
  ExecutorPort,
  ExecutorPortInput,
  ExecutorHandle,
  ExecutorResult,
  CompletionBrokerPort,
} from "@workflow/runtime-abi";
import {
  DISPATCH_STREAM_KEY,
  type DispatchJob,
} from "@workflow/runtime-abi";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface QueueDispatchAdapterOpts {
  /**
   * Redis URL (e.g. "redis://redis:6379").
   * Defaults to REDIS_URL env var, then "redis://redis:6379".
   */
  redisUrl?: string;

  /**
   * Pre-connected Redis client. When provided, redisUrl is ignored.
   * The caller owns the lifecycle (connect / quit).
   * Useful in tests to inject a fake or already-connected client.
   */
  redisClient?: RedisClientType;

  /**
   * CompletionBrokerPort for handle registration before enqueue.
   * If absent, broker.register is skipped (isolated unit tests).
   */
  broker?: CompletionBrokerPort;

  /**
   * Host directory under which per-handle workspace dirs live.
   * Passed to the DispatchJob as executor_workdir base.
   * Defaults to "/workspaces".
   */
  workspacesDir?: string;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

// ── QueueDispatchAdapter ──────────────────────────────────────────────────────

export class QueueDispatchAdapter implements ExecutorPort {
  private readonly broker: CompletionBrokerPort | null;
  private readonly workspacesDir: string;

  private client: RedisClientType | null;
  private readonly ownedClient: boolean; // true when we created the client
  private connected = false;

  constructor(opts: QueueDispatchAdapterOpts = {}) {
    this.broker = opts.broker ?? null;
    this.workspacesDir = opts.workspacesDir ?? "/workspaces";

    if (opts.redisClient) {
      this.client = opts.redisClient;
      this.ownedClient = false;
      // Assume the provided client is already connected.
      this.connected = true;
    } else {
      const url = opts.redisUrl ?? process.env.REDIS_URL ?? "redis://redis:6379";
      this.client = createClient({ url }) as RedisClientType;
      this.ownedClient = true;
    }
  }

  // ── ExecutorPort ──────────────────────────────────────────────────────────

  async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
    const {
      taskId,
      featureId,
      workspaceId,
      handle,
      taskRepoUrl,
      taskRepoBranch,
      taskBaseBranch,
      taskRepoBaseBranch,
      executorWorkdir,
      mgmtRepoUrl,
      callbackUrl,
      nonce,
      budgetTokens,
      implementationModel,
    } = input;

    const startedAt = new Date().toISOString();

    // 1. Register handle with broker BEFORE enqueuing so a callback that
    //    arrives before submit returns is still accepted by the broker.
    if (this.broker) {
      await this.broker.register(handle, nonce, {
        kind: input.kind ?? "impl",
        task_id: taskId,
        feature_id: featureId,
        started_at: startedAt,
      });
    }

    // 2. Build the credential-free DispatchJob payload.
    const job: DispatchJob = {
      handle,
      nonce,
      kind: (input.kind as DispatchJob["kind"]) ?? "impl",
      task_id: taskId,
      feature_id: featureId,
      workspace_id: workspaceId,
      task_repo_url: taskRepoUrl,
      task_repo_branch: taskRepoBranch,
      task_base_branch: taskBaseBranch,
      task_repo_base_branch: taskRepoBaseBranch ?? taskBaseBranch,
      mgmt_repo_url: mgmtRepoUrl,
      executor_workdir: executorWorkdir ?? `${this.workspacesDir}/exec-${handle}`,
      callback_url: callbackUrl,
      enqueued_at: startedAt,
      ...(budgetTokens !== undefined ? { budget_tokens: budgetTokens } : {}),
      ...(implementationModel ? { implementation_model: implementationModel } : {}),
    };

    // 3. XADD to the dispatch stream — serialise each field as a string value
    //    (Redis Streams require string field/value pairs).
    await this._ensureConnected();
    const fields: string[] = [];
    for (const [k, v] of Object.entries(job)) {
      if (v !== undefined) {
        fields.push(k, String(v));
      }
    }
    // redis npm client xAdd: (key, id, fields)
    await (this.client as RedisClientType).xAdd(
      DISPATCH_STREAM_KEY,
      "*",
      Object.fromEntries(
        Object.entries(job)
          .filter(([, v]) => v !== undefined)
          .map(([k, v]) => [k, String(v)]),
      ),
    );

    emit({
      type: "queue_dispatch_enqueued",
      task_id: taskId,
      feature_id: featureId,
      handle,
      stream: DISPATCH_STREAM_KEY,
    });

    return handle;
  }

  /**
   * readResult is a no-op — results arrive via the broker callback, not from a file.
   */
  async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
    return { terminal_status: "failed", blocked_reason: "handle_not_found" };
  }

  /**
   * Acknowledge a completed handle — delegates to broker.ack().
   * Container cleanup is the dispatcher's responsibility.
   */
  async ack(handle: ExecutorHandle): Promise<void> {
    if (this.broker) {
      await this.broker.ack(handle);
    }
  }

  /**
   * Graceful shutdown — quit the owned Redis client if we created it.
   */
  async close(): Promise<void> {
    if (this.ownedClient && this.client) {
      try {
        await (this.client as RedisClientType).quit();
      } catch {
        // best-effort
      }
      this.client = null;
      this.connected = false;
    }
  }

  // ── Internal ─────────────────────────────────────────────────────────────

  private async _ensureConnected(): Promise<void> {
    if (!this.connected && this.client) {
      await (this.client as RedisClientType).connect();
      this.connected = true;
    }
  }
}

