// ── Dispatch reconciler (local-docker only) ─────────────────────────────
// Backstop for stuck in_progress tasks whose execution_handle was enqueued
// but no completion arrived by EXECUTION_DEADLINE. Re-enqueues the job
// (T4 idempotency prevents double-spawn) up to DISPATCH_RECONCILE_MAX_RETRIES.
if (runtimeProfile === "local-docker" && pulledWorkspaceRoots.length > 0) {
  try {
    const reconcileResult = await runDispatchReconciler({
      workspaceRoots: pulledWorkspaceRoots,
      executor: ports.executor,
      broker: ports.broker,
      workspacesDir: workspacesRoot,
      callbackUrl: ports.broker.getCallbackUrl() ?? "",
      budgetTokens: config.budget.max_tokens_per_task,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
      emit,
    });
    if (reconcileResult.reEnqueued > 0 || reconcileResult.blocked > 0) {
      emit({
        type: "dispatch_reconciler_complete",
        reEnqueued: reconcileResult.reEnqueued,
        blocked: reconcileResult.blocked,
      });
    }
  } catch (e) {
    emit({ type: "dispatch_reconciler_error", details: String(e) });
  }
}

