#!/usr/bin/env node
/**
 * Runner wrapper (D6c) — platform-owned entry point for every spawned executor.
 *
 * Exec's the executor binary, reads RESULT_PATH on exit, and POSTs
 * { handle, nonce, result } to $CALLBACK_URL with bounded exponential-backoff
 * retries on transport errors.
 *
 * Environment variables (required when invoked as main):
 *   RESULT_PATH   — path the executor writes result.json to
 *   CALLBACK_URL  — broker HTTP endpoint to POST the completion to
 *   HANDLE        — opaque executor handle passed through to broker
 *   NONCE         — single-use token for broker authentication
 *   EXECUTOR_BIN  — path to the executor JS file
 *                   (default: /workflow/runtime/executors/claude/dist/index.js)
 *
 * All env vars are inherited by the executor subprocess unchanged.
 *
 * Node stdlib only; no node_modules required.
 */

import { spawn } from 'node:child_process';
import { readFileSync, existsSync, rmSync } from 'node:fs';
import * as http from 'node:http';
import * as https from 'node:https';

const DEFAULT_EXECUTOR_BIN = '/workflow/runtime/executors/claude/dist/index.js';
const MAX_ATTEMPTS = 5;
const BASE_DELAY_MS = 500;
const MAX_STDERR_TAIL_LINES = 20;

