const fs = require('fs');
// Validate YAML structure manually by parsing
const content = fs.readFileSync('runtime/orchestrator/templates/docker-compose.local-docker.yml', 'utf8');
// Check for key structural elements
const checks = {
  'has name': content.includes('name: \${COMPOSE_PROJECT_NAME'),
  'has services': content.includes('services:'),
  'has redis': content.includes('  redis:'),
  'has broker': content.includes('  broker:'),
  'has dispatcher': content.includes('  dispatcher:'),
  'has orchestrator-1': content.includes('  orchestrator-1:'),
  'has orchestrator-bundled': content.includes('  orchestrator-bundled:'),
  'has executor': content.includes('  executor:'),
  'orchestrator-1 no socket': !content.includes('orchestrator-1:') || 
    !content.slice(content.indexOf('  orchestrator-1:'), content.indexOf('  orchestrator-bundled:')).includes('/var/run/docker.sock:/var/run/docker.sock'),
  'x-orchestrator no socket': !content.slice(0, content.indexOf('  dispatcher:')).includes('/var/run/docker.sock:/var/run/docker.sock'),
  'dispatcher has socket': content.slice(content.indexOf('  dispatcher:'), content.indexOf('  orchestrator-1:')).includes('/var/run/docker.sock:/var/run/docker.sock'),
  'has networks': content.includes('networks:'),
  'has volumes': content.includes('volumes:'),
  'has PLATFORM_BIN_DIR': content.includes('PLATFORM_BIN_DIR'),
  'has WORKSPACES_DIR': content.includes('WORKSPACES_DIR'),
